async function copyPlainText(v){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(v);return}var a=document.createElement('textarea');a.value=v;a.style.position='fixed';a.style.opacity='0';document.body.appendChild(a);a.select();var ok=document.execCommand('copy');a.remove();if(!ok)throw new Error('Copy was blocked by the browser.');}
function exportEnquiriesCsv(){var cols=[['id','ID'],['name','Name'],['email','Email'],['mobile_number','Mobile'],['company','Business'],['service','Service'],['goal','Project goal'],['status','Status'],['source','Source'],['utm_source','UTM source'],['utm_medium','UTM medium'],['utm_campaign','Campaign'],['landing_page','Landing page'],['current_page','Last page'],['created_at','Received']];function q(v){return '"'+String(v==null?'':v).replace(/"/g,'""')+'"'}var rows=[cols.map(function(c){return q(c[1])}).join(',')];enquiries.forEach(function(x){rows.push(cols.map(function(c){return q(x[c[0]])}).join(','))});var b=new Blob(['\uFEFF'+rows.join('\r\n')],{type:'text/csv;charset=utf-8;'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='aa-growth-studio-enquiries-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(u);toast('CSV export created from '+enquiries.length+' saved enquiries.');}

function fmtDateTime(v){if(!v)return '—';try{return new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){return String(v)}}
